			}
			if r.Context().Err() != nil {
				h.log.DebugContext(r.Context(), "client went away", slog.String("upstream", string(name)))
				httpx.WriteError(w, httpx.NewError(http.StatusBadGateway, httpx.CodeUnavailable, "upstream service unavailable"))
				return
			}
			h.log.WarnContext(r.Context(), "upstream request failed", slog.String("upstream", string(name)), slog.Any("error", err))
			httpx.WriteError(w, httpx.NewError(http.StatusBadGateway, httpx.CodeUnavailable, "upstream service unavailable"))
		},
		ErrorLog: slog.NewLogLogger(h.log.Handler(), slog.LevelWarn),
	}
}

type limitedBody struct {
	io.ReadCloser
	exceeded atomic.Bool
}

func (l *limitedBody) Read(p []byte) (int, error) {
	n, err := l.ReadCloser.Read(p)
	var mbe *http.MaxBytesError
	if err != nil && errors.As(err, &mbe) {
		l.exceeded.Store(true)
	}
	return n, err
}

type recorder struct {
	http.ResponseWriter
	status int
	bytes  int64
}

func (r *recorder) WriteHeader(code int) {
	if r.status == 0 && code >= 200 {
		r.status = code
	}
	r.ResponseWriter.WriteHeader(code)
}

func (r *recorder) Write(b []byte) (int, error) {
	if r.status == 0 {
		r.status = http.StatusOK
	}
	n, err := r.ResponseWriter.Write(b)
	r.bytes += int64(n)
	return n, err
}

func (r *recorder) Flush() {
	if f, ok := r.ResponseWriter.(http.Flusher); ok {
		f.Flush()
	}
}

func (r *recorder) Unwrap() http.ResponseWriter {
	return r.ResponseWriter
}

func (h *Handler) accessLog(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		st := &state{}
		r = r.WithContext(context.WithValue(r.Context(), stateKey{}, st))
		if r.URL.Path == "/healthz" || r.URL.Path == "/readyz" {
			next.ServeHTTP(w, r)
			return
		}
		start := time.Now()
		realIP := RealIP(r.Header)
		rec := &recorder{ResponseWriter: w}
		defer func() {
			status := rec.status
			if status == 0 {
				status = http.StatusOK
			}
			level := slog.LevelInfo
			if status >= 500 {
				level = slog.LevelError
			}
			path := r.URL.EscapedPath()
			if len(path) > maxLoggedPath {
				path = path[:maxLoggedPath]
			}
			h.log.LogAttrs(r.Context(), level, "http request",
				slog.String("method", r.Method),
				slog.String("path", path),
				slog.Int("status", status),
				slog.Int64("bytes", rec.bytes),
				slog.Duration("duration", time.Since(start)),
				slog.String("real_ip", realIP),
				slog.String("remote", r.RemoteAddr),
				slog.String("upstream", string(st.upstream)),
				slog.String("principal", st.principal),
			)
		}()
		next.ServeHTTP(rec, r)
	})
}

func RealIP(hdr http.Header) string {
	v := hdr.Get(RealIPHeader)
	if v == "" {
		return ""
	}
	addr, err := netip.ParseAddr(strings.TrimSpace(v))
	if err != nil {
		return "invalid"
	}
	return addr.String()
}

// The gateway is private to the frontend network. Its trusted nginx frontend
// overwrites X-Real-IP; do not expose the gateway directly to untrusted clients.
// The independent global budget still bounds work if this boundary is violated.
func clientIP(r *http.Request) string {
	if values := r.Header.Values(RealIPHeader); len(values) == 1 {
		if addr, err := netip.ParseAddr(values[0]); err == nil && values[0] == addr.String() {
			return addr.Unmap().String()
		}
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		host = r.RemoteAddr
	}
	if addr, err := netip.ParseAddr(host); err == nil {
		return addr.Unmap().String()
	}
	return "unknown"
}

